function exportTableToCSV(filename) {  
                //declare a JavaScript variable of array type  
                var csv = [];  
                var rows = document.querySelectorAll("table tr");  
                header = ["SerialNo","StoreId","Email","UserName","IsExclusive","ProductId","ProductQty","ProductPrice","TotalProductPrice","TotalPrice","PaymentMode","OrderDate","OrderMessage","OrderPlacedSms"]
                csv.push(header.join(","))
                itemsList.forEach(row=>{
                    var finalArray = []    
                    var preColumns = []
                    var postColumns = []
                    if(itemsList.indexOf(row) == 0){
                        var currentDate = Date.now()
                        var currentDateObj = new Date(currentDate)
                        var serialNo = setOrderID()
                        var name = document.getElementById('user-name').value
                        var email = document.getElementById('user-email').value
                        preColumns = [serialNo,'{{ store.id }}',email,name,'0']
                        postColumns = [String(row[2]*row[3]),String(getTotalAmount()),'cash',currentDateObj.toISOString().slice(0, 19).replace('T', ' '),'offline billed','0']                    
                    }
                    else{
                        preColumns = ['','','','','']
                        postColumns = [String(row[2]*row[3]),'','','','']
                    }
                    result = preColumns.concat([row[0],row[3],row[2]])
                    result = result.concat(postColumns)
                    csv.push(result.join(","));
                })
                //call the function to download the CSV file  
                downloadCSV(csv.join("\n"), filename);  
            }
